import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import "../styles/NewOrder.css";
import Home from "../pages/Home";

const services = [
  {
    id: 35,
    category: "Instagram Views",
    name: "Instagram Views [ Reels / Videos ] [ Instant ]",
    rate: 0.16,
    min: 100,
    max: 100000000,
    description:
      "High-quality Instagram views with fast delivery. Suitable for reels and videos.",
  },
  {
    id: 4990,
    category: "Instagram Followers",
    name: "Instagram Followers [High Quality + Real]",
    rate: 36.17,
    min: 50,
    max: 50000,
    description:
      "High-quality Instagram followers with fast delivery.",
  },
  {
    id: 5505,
    category: "Instagram Likes",
    name: "Instagram Likes [Real Accounts] [Instant Start]",
    rate: 6.03,
    min: 100,
    max: 1000000,
    description:
      "Instagram likes with instant start and fast delivery.",
  },
  {
    id: 6001,
    category: "YouTube Views",
    name: "YouTube Views [Instant] [Worldwide]",
    rate: 2.4,
    min: 100,
    max: 1000000,
    description:
      "Worldwide YouTube views with fast and reliable delivery.",
  },
  {
    id: 6002,
    category: "YouTube Subscribers",
    name: "YouTube Subscribers [High Quality]",
    rate: 48.5,
    min: 50,
    max: 100000,
    description:
      "High-quality YouTube subscribers for your channel.",
  },
  {
    id: 7001,
    category: "Facebook",
    name: "Facebook Page Followers",
    rate: 22.5,
    min: 50,
    max: 500000,
    description:
      "Facebook page followers with quick delivery.",
  },
  {
    id: 8001,
    category: "TikTok",
    name: "TikTok Followers [Fast Delivery]",
    rate: 31.2,
    min: 50,
    max: 500000,
    description:
      "Fast TikTok follower delivery.",
  },
  {
    id: 8002,
    category: "TikTok",
    name: "TikTok Likes [Worldwide]",
    rate: 4.5,
    min: 100,
    max: 1000000,
    description:
      "Worldwide TikTok likes with fast delivery.",
  },
];

const categories = [
  "All Categories",
  ...new Set(services.map((service) => service.category)),
];

function NewOrder() {
  const [category, setCategory] = useState("All Categories");
  const [serviceId, setServiceId] = useState("");
  const [link, setLink] = useState("");
  const [quantity, setQuantity] = useState("");

  // Wallet
  const [walletBalance, setWalletBalance] = useState(0);
  const [walletLoading, setWalletLoading] = useState(true);

  // Order
  const [orderLoading, setOrderLoading] = useState(false);

  const filteredServices = useMemo(() => {
    if (category === "All Categories") {
      return services;
    }

    return services.filter(
      (service) => service.category === category
    );
  }, [category]);

  const selectedService = services.find(
    (service) => String(service.id) === String(serviceId)
  );

  const totalPrice = selectedService
    ? ((Number(quantity) || 0) / 1000) * selectedService.rate
    : 0;

  /*
   * ==========================================
   * FETCH WALLET BALANCE
   * ==========================================
   */

  const fetchWalletBalance = async () => {
    try {
      setWalletLoading(true);

      const response = await axios.get(
        "http://localhost:5000/api/wallet/balance"
      );

      /*
       * Expected response:
       *
       * {
       *   balance: 1250
       * }
       */

      setWalletBalance(Number(response.data.balance) || 0);
    } catch (error) {
      console.error(
        "Error fetching wallet balance:",
        error
      );

      setWalletBalance(0);

      alert("Unable to fetch wallet balance.");
    } finally {
      setWalletLoading(false);
    }
  };

  /*
   * Fetch wallet when page loads
   */

  useEffect(() => {
    fetchWalletBalance();
  }, []);

  /*
   * ==========================================
   * CATEGORY CHANGE
   * ==========================================
   */

  const handleCategoryChange = (value) => {
    setCategory(value);
    setServiceId("");
    setQuantity("");
  };

  /*
   * ==========================================
   * SERVICE CHANGE
   * ==========================================
   */

  const handleServiceChange = (value) => {
    setServiceId(value);

    const service = services.find(
      (item) => String(item.id) === String(value)
    );

    if (service) {
      setQuantity(service.min);
    }
  };

  /*
   * ==========================================
   * CHECK WALLET
   * ==========================================
   */

  const hasSufficientBalance =
    walletBalance >= totalPrice;

  /*
   * ==========================================
   * SUBMIT ORDER
   * ==========================================
   */

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!selectedService) {
      alert("Please select a service.");
      return;
    }

    if (!link.trim()) {
      alert("Please enter a link.");
      return;
    }

    const orderQuantity = Number(quantity);

    if (!orderQuantity) {
      alert("Please enter quantity.");
      return;
    }

    if (
      orderQuantity < selectedService.min ||
      orderQuantity > selectedService.max
    ) {
      alert(
        `Quantity must be between ${selectedService.min.toLocaleString()} and ${selectedService.max.toLocaleString()}.`
      );
      return;
    }

    /*
     * IMPORTANT:
     * Check wallet before submitting
     */

    if (totalPrice > walletBalance) {
      alert(
        `Insufficient wallet balance.\n\nOrder Amount: ₹${totalPrice.toFixed(
          2
        )}\nWallet Balance: ₹${walletBalance.toFixed(
          2
        )}\n\nPlease add funds to your wallet.`
      );

      return;
    }

    try {
      setOrderLoading(true);

      /*
       * Send order to backend
       */

      const response = await axios.post(
        "http://localhost:5000/api/orders",
        {
          serviceId: selectedService.id,
          serviceName: selectedService.name,
          category: selectedService.category,
          link: link.trim(),
          quantity: orderQuantity,
          rate: selectedService.rate,
          amount: totalPrice,
        }
      );

      alert(
        response.data.message ||
          "Order submitted successfully!"
      );

      /*
       * Clear order form
       */

      setServiceId("");
      setLink("");
      setQuantity("");

      /*
       * Fetch latest wallet balance
       */

      await fetchWalletBalance();
    } catch (error) {
      console.error("Order error:", error);

      alert(
        error.response?.data?.message ||
          "Unable to place order."
      );
    } finally {
      setOrderLoading(false);
    }
  };

  return (
    <div className="order-page">

      <Home />

      <main className="order-container">

        {/* ==========================================
            PAGE TITLE
        ========================================== */}

        <div className="order-title">
          <h1>New Order</h1>

          <p>
            Select a service and place a new order.
          </p>
        </div>

        <div className="order-layout">

          {/* ==========================================
              LEFT FORM
          ========================================== */}

          <div className="order-form-card">

            <div className="card-heading">

              <div className="heading-icon">
                +
              </div>

              <div>
                <h2>Create New Order</h2>

                <p>
                  Fill in the details below
                </p>
              </div>

            </div>

            <form onSubmit={handleSubmit}>

              {/* CATEGORY */}

              <div className="form-group">

                <label>
                  Category
                </label>

                <select
                  value={category}
                  onChange={(e) =>
                    handleCategoryChange(
                      e.target.value
                    )
                  }
                >
                  {categories.map((item) => (
                    <option
                      key={item}
                      value={item}
                    >
                      {item}
                    </option>
                  ))}
                </select>

              </div>

              {/* SERVICE */}

              <div className="form-group">

                <label>
                  Service
                </label>

                <select
                  value={serviceId}
                  onChange={(e) =>
                    handleServiceChange(
                      e.target.value
                    )
                  }
                >

                  <option value="">
                    Select a service
                  </option>

                  {filteredServices.map(
                    (service) => (
                      <option
                        key={service.id}
                        value={service.id}
                      >
                        {service.id} -{" "}
                        {service.name}
                      </option>
                    )
                  )}

                </select>

              </div>

              {/* SERVICE INFO */}

              {selectedService && (
                <div className="service-info">

                  <div className="service-info-header">

                    <span>
                      Service #
                      {selectedService.id}
                    </span>

                    <span className="service-badge">
                      {
                        selectedService.category
                      }
                    </span>

                  </div>

                  <h3>
                    {selectedService.name}
                  </h3>

                  <p>
                    {
                      selectedService.description
                    }
                  </p>

                  <div className="service-limits">

                    <div>
                      <span>
                        Rate / 1000
                      </span>

                      <strong>
                        ₹
                        {selectedService.rate.toFixed(
                          2
                        )}
                      </strong>
                    </div>

                    <div>
                      <span>
                        Min
                      </span>

                      <strong>
                        {selectedService.min.toLocaleString()}
                      </strong>
                    </div>

                    <div>
                      <span>
                        Max
                      </span>

                      <strong>
                        {selectedService.max.toLocaleString()}
                      </strong>
                    </div>

                  </div>

                </div>
              )}

              {/* LINK */}

              <div className="form-group">

                <label>
                  Link
                </label>

                <input
                  type="text"
                  value={link}
                  onChange={(e) =>
                    setLink(e.target.value)
                  }
                  placeholder="Enter post, profile or video link"
                />

                <small>
                  Enter the URL where you want the
                  service delivered.
                </small>

              </div>

              {/* QUANTITY */}

              <div className="form-group">

                <label>
                  Quantity
                </label>

                <input
                  type="number"
                  value={quantity}
                  onChange={(e) =>
                    setQuantity(e.target.value)
                  }
                  placeholder={
                    selectedService
                      ? `${selectedService.min} - ${selectedService.max}`
                      : "Enter quantity"
                  }
                  min={selectedService?.min}
                  max={selectedService?.max}
                />

                {selectedService && (
                  <small>
                    Minimum:{" "}
                    {selectedService.min.toLocaleString()}
                    {" | "}
                    Maximum:{" "}
                    {selectedService.max.toLocaleString()}
                  </small>
                )}

              </div>

              {/* WALLET WARNING */}

              {selectedService &&
                quantity &&
                totalPrice > walletBalance && (
                  <div className="wallet-warning">

                    <strong>
                      Insufficient Wallet Balance
                    </strong>

                    <p>
                      Order amount: ₹
                      {totalPrice.toFixed(2)}
                    </p>

                    <p>
                      Available balance: ₹
                      {walletBalance.toFixed(2)}
                    </p>

                    <a href="/add-funds">
                      Add Funds →
                    </a>

                  </div>
                )}

              {/* DRIP FEED */}

              <div className="checkbox-row">

                <input
                  type="checkbox"
                  id="drip"
                />

                <label htmlFor="drip">
                  Enable Drip-feed
                </label>

              </div>

              {/* PLACE ORDER */}

              <button
                type="submit"
                className="place-order-btn"
                disabled={
                  orderLoading ||
                  walletLoading ||
                  !selectedService ||
                  totalPrice > walletBalance
                }
              >

                {orderLoading
                  ? "Placing Order..."
                  : totalPrice > walletBalance
                  ? "Insufficient Balance"
                  : "Place Order"}

              </button>

            </form>

          </div>

          {/* ==========================================
              RIGHT SUMMARY
          ========================================== */}

          <aside className="order-summary">

            <div className="summary-card">

              <div className="summary-title">

                <h2>
                  Order Summary
                </h2>

                <span>
                  ₹
                </span>

              </div>

              <div className="summary-line">

                <span>
                  Service
                </span>

                <strong>
                  {selectedService
                    ? `#${selectedService.id}`
                    : "—"}
                </strong>

              </div>

              <div className="summary-line">

                <span>
                  Category
                </span>

                <strong>
                  {selectedService
                    ? selectedService.category
                    : "—"}
                </strong>

              </div>

              <div className="summary-line">

                <span>
                  Quantity
                </span>

                <strong>
                  {quantity
                    ? Number(
                        quantity
                      ).toLocaleString()
                    : "—"}
                </strong>

              </div>

              <div className="summary-line">

                <span>
                  Rate / 1000
                </span>

                <strong>
                  {selectedService
                    ? `₹${selectedService.rate.toFixed(
                        2
                      )}`
                    : "—"}
                </strong>

              </div>

              <div className="summary-divider" />

              <div className="total-row">

                <span>
                  Total
                </span>

                <strong>
                  ₹{totalPrice.toFixed(2)}
                </strong>

              </div>

              {/* BALANCE CHECK */}

              <div className="summary-line wallet-summary">

                <span>
                  Wallet Balance
                </span>

                <strong>
                  {walletLoading
                    ? "Loading..."
                    : `₹${walletBalance.toFixed(
                        2
                      )}`}
                </strong>

              </div>

              {/* REMAINING BALANCE */}

              {selectedService &&
                quantity &&
                hasSufficientBalance && (
                  <div className="remaining-balance">

                    Remaining after order:{" "}
                    <strong>
                      ₹
                      {(
                        walletBalance -
                        totalPrice
                      ).toFixed(2)}
                    </strong>

                  </div>
                )}

              {/* INSUFFICIENT */}

              {selectedService &&
                quantity &&
                totalPrice > walletBalance && (
                  <div className="summary-insufficient">

                    Insufficient balance

                  </div>
                )}

              <button
                type="button"
                className="summary-order-btn"
                onClick={handleSubmit}
                disabled={
                  orderLoading ||
                  walletLoading ||
                  !selectedService ||
                  totalPrice > walletBalance
                }
              >

                {orderLoading
                  ? "Processing..."
                  : totalPrice > walletBalance
                  ? "Insufficient Balance"
                  : "Confirm Order"}

              </button>

            </div>

            {/* ==========================================
                WALLET CARD
            ========================================== */}

            <div className="balance-card">

              <div className="balance-icon">
                ₹
              </div>

              <div>

                <span>
                  Available Balance
                </span>

                <strong>
                  {walletLoading
                    ? "Loading..."
                    : `₹${walletBalance.toFixed(
                        2
                      )}`}
                </strong>

              </div>

            </div>

            {/* HELP */}

            <div className="help-card">

              <h3>
                Need help?
              </h3>

              <p>
                Make sure your link is public and
                the quantity is within the allowed
                limits.
              </p>

              <a href="/support">
                Contact Support →
              </a>

            </div>

          </aside>

        </div>

        {/* ==========================================
            RECENT ORDERS
        ========================================== */}

        <section className="recent-orders">

          <div className="recent-header">

            <div>

              <h2>
                Recent Orders
              </h2>

              <p>
                Your latest orders
              </p>

            </div>

            <a href="/orders">
              View All
            </a>

          </div>

          <div className="recent-table">

            <div className="recent-row recent-head">

              <span>
                ID
              </span>

              <span>
                Service
              </span>

              <span>
                Quantity
              </span>

              <span>
                Status
              </span>

              <span>
                Amount
              </span>

            </div>

            <div className="recent-row">

              <span>
                #10582
              </span>

              <span>
                Instagram Followers
              </span>

              <span>
                1,000
              </span>

              <span>
                <b className="status-processing">
                  Processing
                </b>
              </span>

              <span>
                ₹36.17
              </span>

            </div>

            <div className="recent-row">

              <span>
                #10581
              </span>

              <span>
                Instagram Likes
              </span>

              <span>
                5,000
              </span>

              <span>
                <b className="status-complete">
                  Completed
                </b>
              </span>

              <span>
                ₹30.15
              </span>

            </div>

            <div className="recent-row">

              <span>
                #10580
              </span>

              <span>
                YouTube Views
              </span>

              <span>
                10,000
              </span>

              <span>
                <b className="status-complete">
                  Completed
                </b>
              </span>

              <span>
                ₹24.00
              </span>

            </div>

          </div>

        </section>

      </main>

    </div>
  );
}

export default NewOrder;
